NAME = 'VulgConte: Vulgata Clementina, Conte editore'
BOOK = 'Esther'

CHAPTERS = {
    1: {
        1: 'Anno secundo, regnante Artaxerxe maximo, prima die mensis Nisan, vidit somnium Mardochæus filius Iairi, filii Semei, filii Cis, de tribu Beniamin:',
        2: 'homo Iudæus, qui habitabat in urbe Susis, vir magnus, et inter primos aulæ regiæ.',
        3: 'Erat autem de eo numero captivorum, quos transtulerat Nabuchodnosor rex Babylonis de Ierusalem cum Iechonia rege Iuda:',
        4: 'et hoc eius somnium fuit: Apparuerunt voces, et tumultus, et tonitrua, et terræmotus, et conturbatio super terram:',
        5: 'et ecce duo dracones magni, paratique contra se in prælium.',
        6: 'Ad quorum clamorem cunctæ concitatæ sunt nationes, ut pugnarent contra gentem iustorum.',
        7: 'Fuitque dies illa tenebrarum et discriminis, tribulationis et angustiæ, et ingens formido super terram.',
        8: 'Conturbataque est gens iustorum timentium mala sua, et præparata ad mortem.',
        9: 'Clamaveruntque ad Deum: et illis vociferantibus, fons parvus creavit in fluvium maximum, et in aquas plurimas redundavit.',
        10: 'Lux et sol ortus est, et humiles exaltati sunt, et devoraverunt inclytos.',
        11: 'Quod cum vidisset Mardochæus, et surrexisset de strato, cogitabat quid Deus facere vellet: et fixum habebat in animo, scire cupiens quid significaret somnium.',
    },
    2: {
        1: 'Morabatur autem eo tempore in aula regis cum Bagatha et Thara eunuchis regis, qui ianitores erant palatii.',
        2: 'Cumque intellexisset cogitationes eorum, et curas diligentius pervidisset, didicit quod conarentur in regem Artaxerxem manus mittere, et nunciavit super eo regi.',
        3: 'Qui de utroque, habita quæstione, confessos iussit duci ad mortem.',
        4: 'Rex autem quod gestum erat, scripsit in commentariis: sed et Mardochæus rei memoriam litteris tradidit.',
        5: 'Præcepitque ei rex, ut in aula palatii moraretur, datis ei pro delatione muneribus.',
        6: 'Aman vero filius Amadathi bugæus erat gloriosissimus coram rege, et voluit nocere Mardochæo, et populo eius pro duobus eunuchis regis, qui fuerant interfecti.',
    },
    3: {
        1: 'In diebus Assueri, qui regnavit ab India usque Æthiopiam super centum viginti septem provincias:',
        2: 'quando sedit in solio regni sui, Susan civitas regni eius exordium fuit.',
        3: 'Tertio igitur anno imperii sui fecit grande convivium cunctis principibus, et pueris suis, fortissimis Persarum, et Medorum inclytis, et præfectis provinciarum coram se,',
        4: 'ut ostenderet divitias gloriæ regni sui, ac magnitudinem, atque iactantiam potentiæ suæ, multo tempore, centum videlicet et octoginta diebus.',
        5: 'Cumque implerentur dies convivii, invitavit omnem populum, qui inventus est in Susan, a maximo usque ad minimum: et iussit septem diebus convivium præparari in vestibulo horti, et nemoris, quod regio cultu et manu consitum erat.',
        6: 'Et pendebant ex omni parte tentoria aerii coloris et carbasini ac hyacinthini, sustentata funibus byssinis, atque purpureis, qui eburneis circulis inserti erant, et columnis marmoreis fulciebantur. Lectuli quoque aurei et argentei, super pavimentum smaragdino et pario stratum lapide, dispositi erant: quod mira varietate pictura decorabat.',
        7: 'Bibebant autem qui invitati erant, aureis poculis, et aliis atque aliis vasis cibi inferebantur. Vinum quoque, ut magnificentia regia dignum erat, abundans, et præcipuum ponebatur.',
        8: 'Nec erat qui nolentes cogeret ad bibendum, sed sicut rex statuerat, præponens mensis singulos de principibus suis ut sumeret unusquisque quod vellet.',
        9: 'Vasthi quoque regina fecit convivium feminarum in palatio, ubi rex Assuerus manere consueverat.',
        10: 'Itaque die septimo, cum rex esset hilarior, et post nimiam potationem incaluisset mero, præcepit Maumam, et Bazatha, et Harbona, et Bagatha, et Abgatha, et Zethar, et Charchas, septem eunuchis, qui in conspectu eius ministrabant,',
        11: 'ut introducerent reginam Vasthi coram rege, posito super caput eius diademate, ut ostenderet cunctis populis et principibus pulchritudinem illius: erat enim pulchra valde.',
        12: 'Quæ renuit, et ad regis imperium, quod per eunuchos mandaverat, venire contempsit. Unde iratus rex, et nimio furore succensus,',
        13: 'interrogavit sapientes, qui ex more regio semper ei aderant, et illorum faciebat cuncta consilio, scientium leges, ac iura maiorum:',
        14: '(erant autem primi et proximi, Charsena, et Sethar, et Admatha, et Tharsis, et Mares, et Marsana, et Mamuchan, septem duces Persarum, atque Medorum, qui videbant faciem regis, et primi post eum residere soliti erant)',
        15: 'cui sententiæ Vasthi regina subiaceret, quæ Assueri regis imperium, quod per eunuchos mandaverat, facere noluisset. Responditque Mamuchan, audiente rege, atque principibus, Non solum regem læsit regina Vasthi, sed et omnes populos, et principes, qui sunt in cunctis provinciis regis Assueri. Egredietur enim sermo reginæ ad omnes mulieres, ut contemnant viros suos, et dicant: Rex Assuerus iussit ut regina Vasthi intraret ad eum, et illa noluit. Atque hoc exemplo omnes principum coniuges Persarum atque Medorum, parvipendent imperia maritorum: unde regis iusta est indignatio. Si tibi placet, egrediatur edictum a facie tua, et scribatur iuxta legem Persarum atque Medorum, quam præteriri illicitum est, ut nequaquam ultra Vasthi ingrediatur ad regem, sed regnum illius, altera, quæ melior est illa, accipiat. Et hoc in omne (quod latissimum est) provinciarum tuarum divulgetur imperium, et cunctæ uxores tam maiorum, quam minorum deferant maritis suis honorem. Placuit consilium eius regi, et principibus: fecitque rex iuxta consilium Mamuchan, et misit epistolas ad universas provincias regni sui, ut quæque gens audire et legere poterat, diversis linguis et litteris, esse viros principes ac maiores in domibus suis: et hoc per cunctos populos divulgari.',
    },
    4: {
        1: 'His ita gestis, postquam regis Assueri indignatio deferbuerat, recordatus est Vasthi, et quæ fecisset, vel quæ passa esset:',
        2: 'dixeruntque pueri regis, ac ministri eius: Quærantur regi puellæ virgines ac speciosæ,',
        3: 'et mittantur qui considerent per universas provincias puellas speciosas et virgines: et adducant eas ad civitatem Susan, et tradant eas in domum feminarum sub manu Egei eunuchi, qui est præpositus et custos mulierum regiarum: et accipiant mundum muliebrem, et cetera ad usus necessaria.',
        4: 'Et quæcumque inter omnes oculis regis placuerit, ipsa regnet pro Vasthi. Placuit sermo regi: et ita, ut suggesserant, iussit fieri.',
        5: 'Erat vir Iudæus in Susan civitate, vocabulo Mardochæus filius Iair, filii Semei, filii Cis, de stirpe Iemini,',
        6: 'qui translatus fuerat de Ierusalem eo tempore, quo Iechoniam regem Iuda Nabuchodonosor rex Babylonis transtulerat,',
        7: 'qui fuit nutritius filiæ fratris sui Edissæ, quæ altero nomine vocabatur Esther: et utrumque parentem amiserat: pulchra nimis, et decora facie. Mortuisque patre eius ac matre, Mardochæus sibi eam adoptavit in filiam.',
        8: 'Cumque percrebruisset regis imperium, et iuxta mandatum illius multæ pulchræ virgines adducerentur Susan, et Egeo traderentur Eunucho; Esther quoque inter ceteras puellas ei tradita est, ut servaretur in numero feminarum.',
        9: 'Quæ placuit ei, et invenit gratiam in conspectu illius. Et præcepit eunucho, ut acceleraret mundum muliebrem, et traderet ei partes suas, et septem puellas speciosissimas de domo regis, et tam ipsam, quam pedissequas eius ornaret atque excoleret.',
        10: 'Quæ noluit indicare ei populum et patriam suam: Mardochæus enim præceperat ei, ut de hac re omnino reticeret:',
        11: 'qui deambulabat quotidie ante vestibulum domus, in qua electæ virgines servabantur, curam agens salutis Esther, et scire volens quid ei accideret.',
        12: 'Cum autem venisset tempus singularum per ordinem puellarum, ut intrarent ad regem, expletis omnibus, quæ ad cultum muliebrem pertinebant, mensis duodecimus vertebatur: ita dumtaxat, ut sex mensibus oleo ungerentur myrrhino, et aliis sex quibusdam pigmentis et aromatibus uterentur.',
        13: 'Ingredientesque ad regem, quidquid postulassent ad ornatum pertinens, accipiebant: et ut eis placuerat, compositæ de triclinio feminarum ad regis cubiculum transibant.',
        14: 'Et quæ intraverat vespere, egrediebatur mane, atque inde in secundas ædes deducebatur, quæ sub manu Susagazi eunuchi erant, qui concubinis regis præsidebat: nec habebat potestatem ad regem ultra redeundi, nisi voluisset rex, et eam venire iussisset ex nomine.',
        15: 'Evoluto autem tempore per ordinem, instabat dies, quo Esther filia Abihail fratris Mardochæi, quam sibi adoptaverat in filiam, deberet intrare ad regem. Quæ non quæsivit muliebrem cultum, sed quæcumque voluit Egeus eunuchus custos virginum, hæc ei ad ornatum dedit. Erat enim formosa valde, et incredibili pulchritudine, omnium oculis gratiosa et amabilis videbatur.',
        16: 'Ducta est itaque ad cubiculum regis Assueri mense decimo, qui vocatur Tebeth, septimo anno regni eius.',
        17: 'Quæsitum est, et inventum: et appensus est uterque eorum in patibulo. Mandatumque est historiis, et annalibus traditum coram rege.',
    },
    5: {
        1: 'Post hæc rex Assuerus exaltavit Aman filium Amadathi, qui erat de stirpe Agag: et posuit solium eius super omnes principes, quos habebat.',
        2: 'Cunctique servi regis, qui in foribus palatii versabantur, flectebant genua, et adorabant Aman: sic enim præceperat eis imperator. Solus Mardochæus non flectebat genu, neque adorabat eum.',
        3: 'Cui dixerunt pueri regis, qui ad fores palatii præsidebant: Cur præter ceteros non observas mandatum regis?',
        4: 'Cumque hoc crebrius dicerent, et ille nollet audire, nuntiaverunt Aman, scire cupientes utrum perseveraret in sententia: dixerat enim eis se esse Iudæum.',
        5: 'Quod cum audisset Aman, et experimento probasset quod Mardochæus non flecteret sibi genu, nec se adoraret, iratus est valde,',
        6: 'et pro nihilo duxit in unum Mardochæum mittere manus suas: audierat enim quod esset gentis Iudææ. Magisque voluit omnem Iudæorum, qui erant in regno Assueri, perdere nationem.',
        7: 'Mense primo (cuius vocabulum est Nisan) anno duodecimo regni Assueri, missa est sors in urnam, quæ Hebraice dicitur phur, coram Aman, quo die et quo mense gens Iudæorum deberet interfici: et exivit mensis duodecimus, qui vocatur Adar.',
        8: 'Dixitque Aman regi Assuero: Est populus per omnes provincias regni tui dispersus, et a se mutuo separatus, novis utens legibus et ceremoniis, insuper et regis scita contemnens. Et optime nosti quod non expediat regno tuo ut insolescat per licentiam.',
        9: 'Si tibi placet, decerne, ut pereat, et decem millia talentorum appendam arcariis gazæ tuæ.',
        10: 'Tulit ergo rex annulum, quo utebatur, de manu sua, et dedit eum Aman filio Amadathi de progenie Agag, hosti Iudæorum,',
        11: 'dixitque ad eum: Argentum, quod tu polliceris, tuum sit. De populo age quod tibi placet.',
        12: 'Vocatique sunt scribæ regis mense primo Nisan, tertiadecima die eiusdem mensis: et scriptum est, ut iusserat Aman, ad omnes satrapas regis, et iudices provinciarum, diversarumque gentium, ut quæque gens legere poterat, et audire pro varietate linguarum ex nomine regis Assueri: et litteræ signatæ ipsius annulo,',
        13: 'missæ sunt per cursores regis ad universas provincias ut occiderent atque delerent omnes Iudæos, a puero usque ad senem, parvulos, et mulieres, uno die, hoc est tertiodecimo mensis duodecimi, qui vocatur Adar, et diriperent bona, vel substantias eorum.',
    },
    6: {
        1: 'Epistolæ autem hoc exemplar fuit: Rex maximus Artaxerxes ab India usque Æthiopiam centum vigintiseptem provinciarum principibus, et ducibus, qui eius imperio subiecti sunt, salutem.',
        2: 'Cum plurimis gentibus imperarem, et universum orbem meæ ditioni subiugassem, volui nequaquam abuti potentiæ magnitudine, sed clementia et lenitate gubernare subiectos, ut absque ullo terrore vitam silentio transigentes, optata cunctis mortalibus pace fruerentur.',
        3: 'Quærente autem me a consiliariis meis quomodo posset hoc impleri, unus qui sapientia et fide ceteros præcellebat, et erat post regem secundus, Aman nomine,',
        4: 'indicavit mihi in toto orbe terrarum populum esse dispersum, qui novis uteretur legibus, et contra omnium gentium consuetudinem faciens, regum iussa contemneret, et universarum concordiam nationum sua dissensione violaret.',
        5: 'Quod cum didicissemus, videntes unam gentem rebellem adversus omne hominum genus perversis, uti legibus, nostrisque iussionibus contraire, et turbare subiectarum nobis provinciarum pacem atque concordiam,',
        6: 'iussimus ut quoscumque Aman, qui omnibus provinciis præpositus est, et secundus a rege, et quem patris loco colimus, monstraverit, cum coniugibus ac liberis deleantur ab inimicis suis, nullusque eorum misereatur, quartadecima die duodecimi mensis Adar anni præsentis:',
        7: 'ut nefarii homines uno die ad inferos descendentes, reddant imperio nostro pacem, quam turbaverant.',
        8: 'Summa autem epistolarum hæc fuit, ut omnes provinciæ scirent, et pararent se ad prædictam diem.',
        9: 'Festinabant cursores, qui missi erant, regis imperium explere. Statimque in Susan pependit edictum, rege et Aman celebrante convivium, et cunctis Iudæis, qui in urbe erant, flentibus.',
    },
    7: {
        1: 'Quæ cum audisset Mardochæus, scidit vestimenta sua, et indutus est sacco, spargens cinerem capiti: et in platea mediæ civitatis voce magna clamabat, ostendens amaritudinem animi sui,',
        2: 'et hoc eiulatu usque ad fores palatii gradiens. Non enim erat licitum indutum sacco aulam regis intrare.',
        3: 'In omnibus quoque provinciis, oppidis, ac locis, ad quæ crudele regis dogma pervenerat, planctus ingens erat apud Iudæos, ieiunium, ululatus, et fletus, sacco et cinere multis pro strato utentibus.',
        4: 'Ingressæ autem sunt puellæ Esther et eunuchi, nuntiaveruntque ei. Quod audiens consternata est: et vestem misit, ut ablato sacco induerent eum: quam accipere noluit.',
        5: 'Accitoque Athach eunucho, quem rex ministrum ei dederat, præcepit ei ut iret ad Mardochæum, et disceret ab eo cur hoc faceret.',
        6: 'Egressusque Athach, ivit ad Mardochæum stantem in platea civitatis, ante ostium palatii:',
        7: 'qui indicavit ei omnia, quæ acciderant, quo modo Aman promisisset, ut in thesauros regis pro Iudæorum nece inferret argentum.',
        8: 'Exemplar quoque edicti, quod pendebat in Susan, dedit ei, ut reginæ ostenderet, et moneret eam, ut intraret ad regem, et deprecaretur eum pro populo suo.',
        9: 'Regressus Athach, nuntiavit Esther omnia, quæ Mardochæus dixerat.',
        10: 'Omnis quoque Israel pari mente et obsecratione clamavit ad Dominum, eo quod eis certa mors impenderet.',
    },
    8: {
        1: 'Esther quoque regina confugit ad Dominum, pavens periculum, quod imminebat.',
        2: 'Cumque deposuisset vestes regias, fletibus et luctui apta indumenta suscepit, et pro unguentis variis, cinere et stercore implevit caput, et corpus suum humiliavit ieiuniis: omniaque loca, in quibus antea lætari consueverat, crinium laceratione complevit.',
        3: 'Et deprecabatur Dominum Deum Israel, dicens: Domine mi, qui Rex noster es solus, adiuva me solitariam, et cuius præter te nullus est auxiliator alius.',
        4: 'Periculum meum in manibus meis est.',
        5: 'Audivi a patre meo quod tu Domine tulisses Israel de cunctis gentibus, et patres nostros ex omnibus retro maioribus suis, ut possideres hereditatem sempiternam, fecistique eis sicut locutus es.',
        6: 'Peccavimus in conspectu tuo, et idcirco tradidisti nos in manus inimicorum nostrorum:',
        7: 'coluimus enim deos eorum. Iustus es Domine:',
        8: 'et nunc non eis sufficit, quod durissima nos opprimunt servitute, sed robur manuum suarum, idolorum potentiæ deputantes,',
        9: 'volunt tua mutare promissa, et delere hereditatem tuam, et claudere ora laudantium te, atque extinguere gloriam templi et altaris tui,',
        10: 'ut aperiant ora Gentium, et laudent idolorum fortitudinem, et prædicent carnalem regem in sempiternum.',
        11: 'Ne tradas Domine sceptrum tuum his, qui non sunt, ne rideant ad ruinam nostram: sed converte consilium eorum super eos, et eum, qui in nos cœpit sævire, disperde.',
        12: 'Memento Domine, et ostende te nobis in tempore tribulationis nostræ, et da mihi fiduciam, Domine Rex deorum, et universæ potestatis:',
        13: 'tribue sermonem compositum in ore meo in conspectu leonis, et transfer cor illius in odium hostis nostri, ut et ipse pereat, et ceteri, qui ei consentiunt.',
        14: 'Nos autem libera manu tua, et adiuva me, nullum aliud auxilium habentem, nisi te, Domine, qui habes omnium scientiam,',
        15: 'et nosti quia oderim gloriam iniquorum, et detester cubile incircumcisorum, et omnis alienigenæ.',
        16: 'Tu scis necessitatem meam, quod abominer signum superbiæ et gloriæ meæ, quod est super caput meum in diebus ostentationis meæ, et detester illud quasi pannum menstruatæ, et non portem in diebus silentii mei,',
        17: 'Deus fortis super omnes, exaudi vocem eorum, qui nullam aliam spem habent, et libera nos de manu iniquorum, et erue me a timore meo.',
    },
    9: {
        1: 'Die autem tertio deposuit vestimenta ornatus sui, et circumdata est gloria sua.',
        2: 'Cumque regio fulgeret habitu, et invocasset omnium rectorem et salvatorem Deum, assumpsit duas famulas,',
        3: 'et super unam quidem innitebatur, quasi præ deliciis et nimia teneritudine corpus suum ferre non sustinens:',
        4: 'altera autem famularum sequebatur dominam, defluentia in humum indumenta sustentans.',
        5: 'Ipsa autem roseo colore vultum perfusa, et gratis ac nitentibus oculis tristem celabat animum, et nimio timore contractum.',
        6: 'Ingressa igitur cuncta per ordinem ostia, stetit contra regem, ubi ille residebat super solium regni sui, indutus vestibus regiis, auroque fulgens, et pretiosis lapidibus, eratque terribilis aspectu.',
        7: 'Cumque elevasset faciem, et ardentibus oculis furorem pectoris indicasset, regina corruit, et in pallorem colore mutato, lassum super ancillulam reclinavit caput.',
        8: 'Convertitque Deus spiritum regis in mansuetudinem, et festinus ac metuens exilivit de solio, et sustentans eam ulnis suis, donec rediret ad se, his verbis blandiebatur:',
        9: 'Quid habes Esther? Ego sum frater tuus, noli metuere.',
        10: 'Non morieris: non enim pro te, sed pro omnibus hæc lex constituta est.',
        11: 'Accede igitur, et tange sceptrum.',
        12: 'Cumque illa reticeret, tulit auream virgam, et posuit super collum eius, et osculatus est eam, et ait: Cur mihi non loqueris?',
        13: 'Quæ respondit: Vidi te domine quasi Angelum Dei, et conturbatum est cor meum præ timore gloriæ tuæ.',
        14: 'Valde enim mirabilis es domine, et facies tua plena est gratiarum.',
        15: 'Cumque loqueretur, rursus corruit, et pene exanimata est.',
        16: 'Rex autem turbabatur, et omnes ministri eius consolabantur eam.',
        17: 'Die autem tertio induta est Esther regalibus vestimentis, et stetit in atrio domus regiæ, quod erat interius, contra basilicam regis: at ille sedebat super solium suum in consistorio palatii contra ostium domus.',
        18: 'Cumque vidisset Esther reginam stantem, placuit oculis eius, et extendit contra eam virgam auream, quam tenebat manu: Quæ accedens, osculata est summitatem virgæ eius:',
        19: 'Dixitque ad eam rex: Quid vis Esther regina? quæ est petitio tua? etiam si dimidiam partem regni petieris, dabitur tibi.',
        20: 'At illa respondit: Si regi placet, obsecro ut venias ad me hodie, et Aman tecum ad convivium, quod paravi.',
        21: 'Statimque rex, Vocate, inquit, cito Aman ut Esther obediat voluntati. Venerunt itaque rex et Aman ad convivium, quod eis regina paraverat.',
        22: 'Dixitque ei rex, postquam vinum biberat abundanter: Quid petis ut detur tibi? et pro qua re postulas? etiam si dimidiam partem regni mei petieris, impetrabis.',
        23: 'Cui respondit Esther: Petitio mea, et preces sunt istæ:',
        24: 'Si inveni in conspectu regis gratiam, et si regi placet ut det mihi quod postulo, et meam impleat petitionem: veniat rex et Aman ad convivium quod paravi eis, et cras aperiam regi voluntatem meam.',
        25: 'Egressus est itaque illo die Aman lætus et alacer. Cumque vidisset Mardochæum sedentem ante fores palatii, et non solum non assurrexisse sibi, sed nec motum quidem de loco sessionis suæ, indignatus est valde:',
        26: 'et dissimulata ira, reversus in domum suam, convocavit ad se amicos suos, et Zares uxorem suam:',
        27: 'et exposuit illis magnitudinem divitiarum suarum, filiorumque turbam, et quanta eum gloria super omnes principes et servos suos rex elevasset.',
        28: 'Et post hæc ait: Regina quoque Esther nullum alium vocavit ad convivium cum rege, præter me: apud quam etiam cras cum rege pransurus sum.',
        29: 'Et cum hæc omnia habeam, nihil me habere puto, quamdiu videro Mardochæum Iudæum sedentem ante fores regias.',
        30: 'Responderuntque ei Zales uxor eius, et ceteri amici: Iube parari excelsam trabem, habentem altitudinis quinquaginta cubitos, et dic mane regi ut appendatur super eam Mardochæus, et sic ibis cum rege lætus ad convivium. Placuit ei consilium, et iussit excelsam parari crucem.',
    },
    10: {
        1: 'Noctem illam duxit rex insomnem, iussitque sibi afferri historias et annales priorum temporum. Quæ cum illo præsente legerentur,',
        2: 'ventum est ad illum locum ubi scriptum erat quo modo nunciasset Mardochæus insidias Bagathan, et Thares eunuchorum, regem Assuerum iugulare cupientium.',
        3: 'Quod cum audisset rex, ait: Quid pro hac fide honoris ac præmii Mardochæus consecutus est? Dixerunt ei servi illius ac ministri: Nihil omnino mercedis accepit.',
        4: 'Statimque rex, Quis est, inquit, in atrio? Aman quippe interius atrium domus regiæ intraverat, ut suggereret regi, et iuberet Mardochæum affigi patibulo, quod ei fuerat præparatum.',
        5: 'Responderunt pueri: Aman stat in atrio. Dixitque rex: Ingrediatur.',
        6: 'Cumque esset ingressus, ait illi: Quid debet fieri viro, quem rex honorare desiderat? Cogitans autem in corde suo Aman, et reputans quod nullum alium rex, nisi se, vellet honorare,',
        7: 'respondit: Homo, quem rex honorare cupit,',
        8: 'debet indui vestibus regiis, et imponi super equum, qui de sella regis est, et accipere regium diadema super caput suum,',
        9: 'et primus de regiis principibus, ac tyrannis teneat equum eius, et per plateam civitatis incedens clamet, et dicat: Sic honorabitur, quemcumque voluerit rex honorare.',
        10: 'Dixitque ei rex: Festina, et sumpta stola et equo, fac, ut locutus es, Mardochæo Iudæo, qui sedet ante fores palatii. Cave ne quidquam de his, quæ locutus es, prætermittas.',
        11: 'Tulit itaque Aman stolam et equum, indutumque Mardochæum in platea civitatis, et impositum equo præcedebat, atque clamabat: Hoc honore condignus est, quemcumque rex voluerit honorare.',
        12: 'Reversusque est Mardochæus ad ianuam palatii: et Aman festinavit ire in domum suam, lugens et operto capite:',
        13: 'Adhuc illis loquentibus, venerunt eunuchi regis, et cito eum ad convivium, quod regina paraverat, pergere compulerunt.',
    },
    11: {
        1: 'Intravit itaque rex et Aman, ut biberent cum regina.',
        2: 'Dixitque ei rex etiam secunda die, postquam vino incaluerat: Quæ est petitio tua Esther ut detur tibi? et quid vis fieri? etiam si dimidiam partem regni mei petieris, impetrabis.',
        3: 'Ad quem illa respondit: Si inveni gratiam in oculis tuis o rex, et si tibi placet, dona mihi animam meam pro qua rogo, et populum meum pro quo obsecro.',
        4: 'Traditi enim sumus ego et populus meus, ut conteramur, iugulemur, et pereamus. Atque utinam in servos et famulas venderemur: esset tolerabile malum, et gemens tacerem: nunc autem hostis noster est, cuius crudelitas redundat in regem.',
        5: 'Respondensque rex Assuerus ait: Quis est iste, et cuius potentiæ, ut hæc audeat facere?',
        6: 'Dixitque Esther: Hostis et inimicus noster pessimus iste est Aman. Quod ille audiens, illico obstupuit, vultum regis ac reginæ ferre non sustinens.',
        7: 'Rex autem iratus surrexit, et de loco convivii intravit in hortum arboribus consitum. Aman quoque surrexit ut rogaret Esther reginam pro anima sua, intellexit enim a rege sibi paratum malum.',
        8: 'Qui cum reversus esset de horto nemoribus consito, et intrasset convivii locum, reperit Aman super lectulum corruisse, in quo iacebat Esther, et ait: Etiam reginam vult opprimere, me præsente, in domo mea. Necdum verbum de ore regis exierat, et statim operuerunt faciem eius.',
        9: 'Dixitque Harbona, unus de eunuchis, qui stabant in ministerio regis: En lignum, quod paraverat Mardochæo, qui locutus est pro rege, stat in domo Aman, habens altitudinis quinquaginta cubitos. Cui dixit rex: Appendite eum in eo.',
        10: 'Suspensus est itaque Aman in patibulo quod paraverat Mardochæo: et regis ira quievit.',
    },
    12: {
        1: 'Die illo dedit rex Assuerus Esther reginæ domum Aman adversarii Iudæorum, et Mardochæus ingressus est ante faciem regis. Confessa est enim ei Esther quod esset patruus suus.',
        2: 'Tulitque rex annulum, quem ab Aman recipi iusserat, et tradidit Mardochæo. Esther autem constituit Mardochæum super domum suam.',
        3: 'Nec his contenta, procidit ad pedes regis, flevitque et locuta ad eum oravit ut malitiam Aman Agagitæ, et machinationes eius pessimas, quas excogitaverat contra Iudæos, iuberet irritas fieri.',
        4: 'At ille ex more sceptrum aureum protendit manu, quo signum clementiæ monstrabatur: illaque consurgens stetit ante eum,',
        5: 'et ait: Si placet regi, et si inveni gratiam in oculis eius, et deprecatio mea non ei videtur esse contraria, obsecro, ut novis epistolis, veteres Aman litteræ, insidiatoris et hostis Iudæorum, quibus eos in cunctis regis provinciis perire præceperat, corrigantur.',
        6: 'Et constituta est per omnes provincias una ultionis dies, id est tertiadecima mensis duodecimi Adar.',
    },
    13: {
        1: 'Rex magnus Artaxerxes ab India usque Æthiopiam centum vigintiseptem provinciarum ducibus ac principibus, qui nostræ iussioni obediunt, salutem dicit.',
        2: 'Multi bonitate principum et honore, qui in eos collatus est, abusi sunt in superbiam:',
        3: 'et non solum subiectos regibus nituntur opprimere, sed datam sibi gloriam non ferentes, in ipsos, qui dederunt, moliuntur insidias.',
        4: 'Nec contenti sunt gratias non agere beneficiis, et humanitatis in se iura violare, sed Dei quoque cuncta cernentis arbitrantur se posse fugere sententiam.',
        5: 'Et in tantum vesaniæ proruperunt, ut eos, qui credita sibi officia diligenter observant, et ita cuncta agunt ut omnium laude digni sint, mendaciorum cuniculis conentur subvertere,',
        6: 'dum aures principum simplices, et ex sua natura alios æstimantes, callida fraude decipiunt.',
        7: 'Quæ res et ex veteribus probatur historiis, et ex his, quæ geruntur quotidie, quomodo malis quorumdam suggestionibus regum studia depraventur.',
        8: 'Unde providendum est paci omnium provinciarum.',
        9: 'Nec putare debetis, si diversa iubeamus, ex animi nostri venire levitate, sed pro qualitate et necessitate temporum, ut reipublicæ poscit utilitas, ferre sententiam.',
        10: 'Et ut manifestius quod dicimus, intelligatis, Aman filius Amadathi, et animo et gente Macedo, alienusque a Persarum sanguine, et pietatem nostram sua crudelitate commaculans, peregrinus a nobis susceptus est:',
        11: 'et tantam in se expertus humanitatem, ut pater noster vocaretur, et adoraretur ab omnibus post regem secundus:',
        12: 'qui in tantum arrogantiæ tumorem sublatus est, ut regno privare nos niteretur et spiritu.',
        13: 'Nam Mardochæum, cuius fide et beneficiis vivimus, et consortem regni nostri Esther cum omni gente sua novis quibusdam atque inauditis machinis expetivit in mortem:',
        14: 'hoc cogitans ut illis interfectis, insidiaretur nostræ solitudini, et regnum Persarum transferret in Macedonas.',
        15: 'Nos autem a pessimo mortalium Iudæos neci destinatos, in nulla penitus culpa reperimus, sed e contrario iustis utentes legibus,',
        16: 'et filios altissimi et maximi, semperque viventis Dei, cuius beneficio et patribus nostris et nobis regnum est traditum, et usque hodie custoditur.',
        17: 'Unde eas litteras, quas sub nomine nostro ille direxerat, sciatis esse irritas.',
        18: 'Apud omnes populos, urbes, atque provincias, quocumque regis iussa veniebant, mira exultatio, epulæ atque convivia, et festus dies: in tantum ut plures alterius gentis et sectæ eorum religioni et ceremoniis iungerentur. Grandis enim cunctos Iudaici nominis terror invaserat.',
    },
    14: {
        1: 'Igitur duodecimi mensis, quem Adar vocari ante iam diximus, tertiadecima die, quando cunctis Iudæis interfectio parabatur, et hostes eorum inhiabant sanguini, versa vice Iudæi superiores esse cœperunt, et se de adversariis vindicare.',
        2: 'Congregatique sunt per singulas civitates, oppida, et loca ut extenderent manum contra inimicos, et persecutores suos. Nullusque ausus est resistere, eo quod omnes populos magnitudinis eorum formido penetrarat.',
        3: 'Nam et provinciarum iudices, et duces, et procuratores, omnisque dignitas, quæ singulis locis ac operibus præerat, extollebant Iudæos timore Mardochæi:',
        4: 'quem principem esse palatii, et plurimum posse cognoverant: fama quoque nominis eius crescebat quotidie, et per cunctorum ora volitabat.',
        5: 'Itaque percusserunt Iudæi inimicos suos plaga magna, et occiderunt eos, reddentes eis quod sibi paraverant facere:',
        6: 'in tantum ut etiam in Susan quingentos viros interficerent, extra decem filios Aman Agagitæ hostis Iudæorum: quorum ista sunt nomina:',
        7: 'Pharsandatha, et Delphon, et Esphatha,',
        8: 'et Phoratha, et Adalia, et Aridatha,',
        9: 'et Phermesta et Arisai, et Aridai, et Iezatha.',
        10: 'Quos cum occidissent, prædas de substantiis eorum tangere noluerunt.',
        11: 'Statimque numerus eorum, qui occisi erant in Susan, ad regem relatus est.',
        12: 'Qui dixit reginæ: In urbe Susan interfecerunt Iudæi quingentos viros, et alios decem filios Aman: quantam putas eos exercere cædem in universis provinciis? Quid ultra postulas, et quid vis ut fieri iubeam?',
        13: 'Cui illa respondit: Si regi placet, detur potestas Iudæis, ut sicut fecerunt hodie in Susan, sic et cras faciant, et decem filii Aman in patibulis suspendantur.',
        14: 'Præcepitque rex ut ita fieret. Statimque in Susan pependit edictum, et decem filii Aman suspensi sunt.',
        15: 'Congregatis Iudæis quartadecima die mensis Adar, interfecti sunt in Susan trecenti viri: nec eorum ab illis direpta substantia est.',
        16: 'Sed et per omnes provincias, quæ ditioni regis subiacebant, pro animabus suis steterunt Iudæi, interfectis hostibus ac persecutoribus suis: in tantum ut septuagintaquinque millia occisorum implerentur, et nullus de substantiis eorum quidquam contingeret.',
        17: 'Dies autem tertiusdecimus mensis Adar primus apud omnes interfectionis fuit, et quartadecima die cædere desierunt. Quem constituerunt esse sollemnem, ut in eo omni tempore deinceps vacarent epulis, gaudio atque conviviis.',
        18: 'At hi, qui in urbe Susan cædem exercuerant, tertiodecimo et quartodecimo die eiusdem mensis in cæde versati sunt: quintodecimo autem die percutere desierunt. Et idcirco eundem diem constituerunt sollemnem epularum atque lætitiæ.',
        19: 'et omnia, quæ libri huius, qui vocatur Esther, historia continentur.',
    },
    15: {
        1: 'Rex vero Assuerus omnem terram, et cunctas maris insulas fecit tributarias:',
        2: 'cuius fortitudo et imperium, et dignitas atque sublimitas, qua exaltavit Mardochæum, scripta sunt in libris Medorum, atque Persarum:',
        3: 'et quomodo Mardochæus Iudaici generis secundus a rege Assuero fuerit: et magnus apud Iudæos et acceptabilis plebi fratrum suorum, quærens bona populo suo, et loquens ea, quæ ad pacem seminis sui pertinerent.',
        4: 'Dixitque Merdochæus: A Deo facta sunt ista.',
        5: 'Recordatus sum somnii, quod videram, hæc eadem significantis: nec eorum quidquam irritum fuit.',
        6: 'Parvus fons, qui crevit in fluvium, et in lucem, solemque conversus est, et in aquas plurimas redundavit: Esther est, quam rex accepit uxorem, et voluit esse reginam.',
        7: 'Duo autem dracones: ego sum, et Aman.',
        8: 'Gentes, quæ convenerant: hi sunt, qui conati sunt delere nomen Iudæorum.',
        9: 'Gens autem mea: Israel est, quæ clamavit ad Dominum, et salvum fecit Dominus populum suum: liberavitque nos ab omnibus malis, et fecit signa magna atque portenta inter Gentes:',
        10: 'et duas sortes esse præcepit, unam Populi Dei, et alteram cunctarum Gentium.',
        11: 'Venitque utraque sors in statutum ex illo iam tempore diem coram Deo universis gentibus:',
        12: 'et recordatus est Dominus populi sui, ac misertus est hereditatis suæ.',
        13: 'Et observabuntur dies isti in mense Adar quartadecima, et quintadecima die eiusdem mensis, cum omni studio, et gaudio in unum cœtum populi congregati, in cunctas deinceps generationes populi Israel.',
        14: 'Anno quarto regnantibus Ptolemæo, et Cleopatra, attulerunt Dosithæus, qui se Sacerdotem, et Levitici generis ferebat, et Ptolemæus filius eius hanc epistolam phurim, quam dixerunt interpretatum esse Lysimachum Ptolemæi filium in Ierusalem.',
    },
}
